'use client'

import { useEffect, useId, useRef, useState } from 'react'
import type { CSSProperties, KeyboardEvent, ReactNode } from 'react'
import './spine-archive.css'

export interface SpineArchiveItem {
  /** A stable, unique identifier. */
  id: string
  title: string
  year?: string
  category?: string
  color?: string
  foreground?: string
  /** Decorative artwork only. Do not include links, buttons, or form controls. */
  artwork?: ReactNode
  description?: string
  href?: string
}

export interface SpineArchiveProps {
  items: SpineArchiveItem[]
  defaultValue?: string
  className?: string
  /** Called when a visitor commits a selection by clicking, tapping, or pressing Enter/Space. */
  onValueChange?: (value: string) => void
}

/** An expandable shelf of physical-looking project sleeves. */
export function SpineArchive({
  items,
  defaultValue,
  className = '',
  onValueChange,
}: SpineArchiveProps) {
  const instanceId = useId()
  const rackRef = useRef<HTMLDivElement>(null)
  const triggerRefs = useRef<Array<HTMLButtonElement | null>>([])
  const revealFrame = useRef<number | null>(null)
  const [selectedId, setSelectedId] = useState(defaultValue ?? items[0]?.id)
  const [pointerId, setPointerId] = useState<string>()
  const [focusId, setFocusId] = useState<string>()
  const validId = (id: string | undefined) => items.some((item) => item.id === id)
  const committedId = validId(selectedId) ? selectedId : items[0]?.id
  const activeId = validId(pointerId) ? pointerId : validId(focusId) ? focusId : committedId
  const activeIndex = items.findIndex((item) => item.id === activeId)

  // Keep keyboard and touch selections inside this shelf without scrolling the page.
  function reveal(index: number) {
    if (revealFrame.current !== null) cancelAnimationFrame(revealFrame.current)
    const startedAt = performance.now()
    const duration = window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 500
    function keepVisible(time: number) {
      const rack = rackRef.current
      const sleeve = triggerRefs.current[index]?.parentElement
      if (!rack || !sleeve) {
        revealFrame.current = null
        return
      }
      const shelfBox = rack.getBoundingClientRect()
      const sleeveBox = sleeve.getBoundingClientRect()
      if (sleeveBox.left < shelfBox.left + 12) {
        rack.scrollLeft += sleeveBox.left - shelfBox.left - 12
      } else if (sleeveBox.right > shelfBox.right - 12) {
        rack.scrollLeft += sleeveBox.right - shelfBox.right + 12
      }
      // The sleeve grows after focus. Follow that change until its transition ends.
      revealFrame.current = time - startedAt < duration ? requestAnimationFrame(keepVisible) : null
    }
    revealFrame.current = requestAnimationFrame(keepVisible)
  }

  useEffect(() => () => {
    if (revealFrame.current !== null) cancelAnimationFrame(revealFrame.current)
  }, [])

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let nextIndex: number
    switch (event.key) {
      case 'ArrowRight':
        nextIndex = (index + 1) % items.length
        break
      case 'ArrowLeft':
        nextIndex = (index - 1 + items.length) % items.length
        break
      case 'Home':
        nextIndex = 0
        break
      case 'End':
        nextIndex = items.length - 1
        break
      default:
        return
    }
    event.preventDefault()
    setPointerId(undefined)
    triggerRefs.current[nextIndex]?.focus({ preventScroll: true })
    reveal(nextIndex)
  }

  return (
    <section
      className={`ac-spine-archive ${className}`.trim()}
      aria-label="Project archive"
      onPointerLeave={() => setPointerId(undefined)}
      onBlur={(event) => {
        if (!(event.relatedTarget instanceof Node) || !event.currentTarget.contains(event.relatedTarget)) {
          setFocusId(undefined)
        }
      }}
    >
      <div className="ac-spine-heading" aria-hidden="true">
        <span>Selected archive</span>
        <span>{String(Math.max(activeIndex + 1, 0)).padStart(2, '0')} / {String(items.length).padStart(2, '0')}</span>
      </div>
      <div className="ac-spine-rack" ref={rackRef}>
        {items.map((item, index) => {
          const isActive = activeId === item.id
          const isSelected = committedId === item.id
          const triggerId = `${instanceId}-spine-${index}`
          const detailsId = `${instanceId}-details-${index}`
          const style = {
            '--ac-spine-cover-color': item.color ?? '#ddfa6b',
            '--ac-spine-ink': item.foreground ?? '#191a17',
          } as CSSProperties

          return (
            <article
              className="ac-spine-sleeve"
              data-active={isActive}
              data-selected={isSelected}
              key={item.id}
              style={style}
              onPointerEnter={(event) => {
                if (event.pointerType === 'mouse' && window.matchMedia('(hover: hover) and (pointer: fine)').matches) {
                  const focused = document.activeElement
                  if (focused instanceof HTMLElement && rackRef.current?.contains(focused) && focused.matches(':focus-visible')) return
                  setPointerId(item.id)
                }
              }}
              onFocus={() => {
                setPointerId(undefined)
                setFocusId(item.id)
                reveal(index)
              }}
            >
              <button
                className="ac-spine-trigger"
                type="button"
                id={triggerId}
                ref={(element) => { triggerRefs.current[index] = element }}
                aria-label={`Select ${item.title}${item.year ? `, ${item.year}` : ''}`}
                aria-expanded={isActive}
                aria-controls={detailsId}
                aria-pressed={isSelected}
                onKeyDown={(event) => handleKeyDown(event, index)}
                onClick={() => {
                  setSelectedId(item.id)
                  setPointerId(undefined)
                  setFocusId(item.id)
                  onValueChange?.(item.id)
                  reveal(index)
                }}
              >
                <span className="ac-spine-surface" aria-hidden="true">
                  <span className="ac-spine-artwork">
                    {item.artwork ?? <span className="ac-spine-default-art" />}
                  </span>
                  <span className="ac-spine-case-line" />
                  <span className="ac-spine-title">{item.title}</span>
                  <span className="ac-spine-serial">AC—{String(index + 1).padStart(3, '0')}</span>
                  <span className="ac-spine-year">{item.year ?? String(index + 1).padStart(2, '0')}</span>
                </span>
              </button>
              <div
                className="ac-spine-details"
                id={detailsId}
                role="region"
                aria-labelledby={triggerId}
                hidden={!isActive}
              >
                {item.category && <p className="ac-spine-category">{item.category}</p>}
                {item.description && <p className="ac-spine-description">{item.description}</p>}
                {item.href && <a className="ac-spine-link" href={item.href}>Explore project <span aria-hidden="true">↗</span></a>}
              </div>
            </article>
          )
        })}
      </div>
      <div className="ac-spine-footer" aria-hidden="true">
        <span>A collection worth pulling apart.</span>
        <span>← Explore →</span>
      </div>
    </section>
  )
}

.ac-spine-archive {
  container-type: inline-size;
  display: grid;
  grid-template-rows: auto minmax(238px, 1fr) auto;
  gap: 8px;
  box-sizing: border-box;
  width: 100%;
  height: var(--ac-spine-height, 100%);
  min-height: var(--ac-spine-min-height, 320px);
  padding: var(--ac-spine-padding, 18px 20px 16px);
  background: var(--ac-spine-background, #eeece5);
  color: var(--ac-spine-color, #24251f);
  text-align: left;
}

.ac-spine-heading,
.ac-spine-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 9px;
  font-weight: 500;
  line-height: 1.4;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.ac-spine-heading {
  padding-bottom: 5px;
  border-bottom: 1px solid color-mix(in srgb, currentColor 22%, transparent);
}

.ac-spine-footer {
  color: color-mix(in srgb, currentColor 64%, transparent);
  font-size: 8px;
  letter-spacing: 0.01em;
}

.ac-spine-rack {
  display: flex;
  align-items: stretch;
  gap: var(--ac-spine-gap, 7px);
  min-width: 0;
  min-height: 0;
  padding: 17px 12px 16px;
  margin-inline: -12px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-padding-inline: 12px;
  scrollbar-width: thin;
  scrollbar-color: #77796d transparent;
  perspective: 1400px;
}

.ac-spine-sleeve {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 0 0 auto;
  width: max(44px, var(--ac-spine-width, 56px));
  min-height: 208px;
  border-radius: 4px 7px 7px 4px;
  background: var(--ac-spine-cover-color);
  box-shadow: 3px 3px 0 color-mix(in srgb, var(--ac-spine-cover-color) 45%, #111), 7px 10px 10px #16170e26, inset 1px 0 0 #fff5;
  transform: rotateY(-12deg) translateY(3px);
  transform-style: preserve-3d;
  transition: width 460ms cubic-bezier(0.2, 0.8, 0.2, 1), transform 460ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.ac-spine-sleeve[data-active='true'] {
  width: var(--ac-spine-open-width, clamp(190px, 37cqw, 264px));
  transform: rotateY(-5deg) translateY(-5px);
}

.ac-spine-trigger {
  position: relative;
  display: block;
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  border-radius: 4px 7px 7px 4px;
  background: var(--ac-spine-cover-color);
  color: var(--ac-spine-ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.ac-spine-trigger::after {
  position: absolute;
  inset: 0;
  border: 1px solid #0003;
  border-radius: inherit;
  background: linear-gradient(90deg, #fff2, transparent 5%, #0002 8%, transparent 13%, transparent 95%, #0002);
  pointer-events: none;
  content: '';
}

.ac-spine-trigger:focus-visible {
  outline: 2px solid var(--ac-spine-focus, #293feb);
  outline-offset: 5px;
}

.ac-spine-surface {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
}

.ac-spine-artwork {
  position: absolute;
  inset: 0 0 auto;
  height: 29%;
  overflow: hidden;
  background: var(--ac-spine-ink);
  color: var(--ac-spine-cover-color);
  transition: height 460ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.ac-spine-artwork > * {
  display: block;
  width: 100%;
  height: 100%;
}

.ac-spine-sleeve[data-active='true'] .ac-spine-artwork {
  height: 48%;
}

.ac-spine-default-art {
  position: relative;
  background: repeating-linear-gradient(125deg, transparent 0 9px, currentColor 9px 12px, transparent 12px 18px);
}

.ac-spine-default-art::after {
  position: absolute;
  inset: 16% 26%;
  border: 10px solid var(--ac-spine-cover-color);
  border-radius: 50%;
  background: var(--ac-spine-ink);
  content: '';
}

.ac-spine-case-line {
  position: absolute;
  inset: 29% 0 auto;
  height: 6px;
  border-block: 1px solid currentColor;
  opacity: 0.45;
  transition: top 460ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.ac-spine-sleeve[data-active='true'] .ac-spine-case-line {
  top: 48%;
}

.ac-spine-title {
  position: absolute;
  top: calc(29% + 19px);
  bottom: 38px;
  left: 50%;
  overflow: hidden;
  max-height: calc(71% - 58px);
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.05em;
  text-transform: uppercase;
  text-overflow: ellipsis;
  white-space: nowrap;
  writing-mode: vertical-rl;
  transform: translateX(-50%);
}

.ac-spine-sleeve[data-active='true'] .ac-spine-title {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  inset: calc(48% + 12px) 17px auto;
  max-height: calc(52% - 18px);
  font-size: clamp(22px, 4.3cqw, 30px);
  line-height: 0.95;
  white-space: normal;
  writing-mode: horizontal-tb;
  transform: none;
}

.ac-spine-serial,
.ac-spine-year {
  position: absolute;
  bottom: 12px;
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 8px;
  line-height: 1;
  letter-spacing: 0.05em;
}

.ac-spine-serial {
  left: 50%;
  transform: translateX(-50%);
}

.ac-spine-year {
  right: 17px;
  display: none;
}

.ac-spine-sleeve[data-active='true'] .ac-spine-serial {
  top: 10px;
  bottom: auto;
  left: 10px;
  color: var(--ac-spine-cover-color);
  text-shadow: 0 1px 3px var(--ac-spine-ink);
  transform: none;
}

.ac-spine-sleeve[data-active='true'] .ac-spine-year {
  display: block;
  top: 10px;
  right: 10px;
  bottom: auto;
  color: var(--ac-spine-cover-color);
  text-shadow: 0 1px 3px var(--ac-spine-ink);
}

.ac-spine-details {
  position: relative;
  flex: 0 0 auto;
  z-index: 1;
  padding: 2px 17px 14px;
  color: var(--ac-spine-ink);
}

.ac-spine-details[hidden] {
  display: none;
}

.ac-spine-category {
  margin: 0 0 5px;
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 8px;
  font-weight: 500;
  line-height: 1.3;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  opacity: 0.7;
}

.ac-spine-description {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  margin: 0 0 8px;
  font-size: 10px;
  line-height: 1.45;
  opacity: 0.8;
}

.ac-spine-link {
  display: inline-flex;
  min-height: 28px;
  align-items: center;
  gap: 16px;
  color: inherit;
  font-size: 10px;
  font-weight: 600;
  line-height: 1.2;
  text-decoration: underline;
  text-underline-offset: 3px;
  pointer-events: auto;
}

.ac-spine-link:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 4px;
  border-radius: 1px;
}

@container (max-width: 360px) {
  .ac-spine-footer span:first-child {
    max-width: 148px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ac-spine-sleeve,
  .ac-spine-artwork,
  .ac-spine-case-line {
    transition: none;
  }
}
